function TeamBadge({ team, size = 40 }) {
  const crest = CRESTS[team.clubId || team.id];
  if (crest) {
    return (
      <div
        style={{
          width: size,
          height: size,
          borderRadius: "50%",
          background: "#fff",
          flexShrink: 0,
          boxShadow: "0 2px 4px rgba(0,0,0,0.25)",
          overflow: "hidden",
          border: `1px solid ${C.pitch}22`,
        }}
      >
        <img
          src={crest}
          alt={team.name}
          style={{
            width: "142%",
            height: "142%",
            objectFit: "contain",
            position: "relative",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
          }}
        />
      </div>
    );
  }
  const initials = team.name
    .replace(/GAA|Hurling Club|CLG/gi, "")
    .trim()
    .split(/\s+/)
    .map((w) => w[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        background: `radial-gradient(circle at 30% 25%, ${team.color}dd, ${team.color})`,
        color: "#fff",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Oswald, sans-serif",
        fontWeight: 600,
        fontSize: size * 0.4,
        flexShrink: 0,
        boxShadow: "0 2px 4px rgba(0,0,0,0.25)",
      }}
    >
      {initials}
    </div>
  );
}

function StatusPill({ status }) {
  const map = {
    scheduled: { bg: "#EDE7DA", fg: C.inkSoft, label: "Scheduled" },
    live: { bg: C.sliotar, fg: C.ink, label: "● Live" },
    finished: { bg: C.pitch, fg: "#fff", label: "Full time" },
  };
  const s = map[status] || map.scheduled;
  return (
    <span
      style={{
        background: s.bg,
        color: s.fg,
        fontSize: 11,
        fontWeight: 700,
        padding: "3px 8px",
        borderRadius: 20,
        fontFamily: "Inter, sans-serif",
        letterSpacing: 0.3,
      }}
    >
      {s.label}
    </span>
  );
}

